      en: "A UNESCO Global Geopark in Hà Giang province, known for its dramatic karst landscape, deep canyons, and the culture of local ethnic groups.",
      es: "Un Geoparque Mundial de la UNESCO en la provincia de Hà Giang, conocido por su dramático paisaje kárstico, cañones profundos y la cultura de los grupos étnicos locales.",
      pt: "Um Geoparque Mundial da UNESCO na província de Hà Giang, conhecido pela sua dramática paisagem cárstica, desfiladeiros profundos e a cultura dos grupos étnicos locais.",
