      en: ["80% of the area is covered by limestone.", "The Ma Pi Leng Pass offers spectacular views.", "Home to 17 ethnic minorities.", "Paleontological and geological significance."],
      es: ["El 80% de la superficie está cubierta de piedra caliza.", "El paso de Ma Pi Leng ofrece vistas espectaculares.", "Hogar de 17 minorías étnicas.", "Importancia paleontológica y geológica."],
