      es: "Un río que fluye por el cañón más profundo del sudeste asiático, el cañón Tu San, bajo el paso de Ma Pi Leng en la provincia de Hà Giang.",
      pt: "Um rio que flui pelo desfiladeiro mais profundo do Sudeste Asiático, o Tu San Canyon, abaixo do desfiladeiro Ma Pi Leng, na província de Hà Giang.",
      fr: "Une rivière qui coule à travers le canyon le plus profond d'Asie du Sud-Est, le canyon de Tu San, sous le col de Ma Pi Leng dans la province de Hà Giang.",
