      hu: ["Az egyetlen park Vietnámban, amely ezt az erdőtípust védi.", "Elefántok, gaurok, bantengok és leopárdok otthona.", "A Serepok folyó áthalad a parkon.", "Fontos hely a biodiverzitás megőrzése szempontjából."],
