      pt: ["O único parque no Vietname que protege este tipo de floresta.", "Lar de elefantes, gauros, bantengues e leopardos.", "O rio Serepok corre através do parque.", "Local importante para a conservação da biodiversidade."],
      fr: ["Le seul parc du Vietnam protégeant ce type de forêt.", "Abrite des éléphants, des gaurs, des bantengs et des léopards.", "La rivière Serepok traverse le parc.", "Site crucial pour la préservation de la biodiversité."],
