      en: "A UNESCO Biosphere Reserve on the outskirts of Ho Chi Minh City. It is a vast wetland that was destroyed during the war and later reforested.",
      es: "Una Reserva de la Biosfera de la UNESCO a las afueras de la ciudad Ho Chi Minh. Es un vasto humedal destruido durante la guerra y reforestado posteriormente.",
